  @location(5) sunDirection: vec3<f32>,
  @location(6) sunColor: vec3<f32>,
  @location(7) sunIntensity: f32,
  @location(8) ambientIntensity: f32,
  @location(9) ambientColor: vec3<f32>,
  @location(10) height: f32,
  @location(11) slope: f32,
