  var texCoord: vec2<f32>;
  texCoord.x = (position.x + 1) / 2;
  texCoord.y = (position.y + 1) / 2;

  var position3D = vec3<f32>(position.x, 0, position.y);

  let clampedCoord = clamp(texCoord * uniforms.heightResolution, vec2<f32>(0.0), uniforms.heightResolution - vec2<f32>(1.0));
  let texPosition = vec2<i32>(clampedCoord);
  var height = textureLoad(storageTexture, texPosition, 0).r;

