  output.sunDirection = uniforms.sunDirection;
  output.sunPosition = uniforms.sunPosition;
  output.sunColor = uniforms.sunColor;
  output.sunIntensity = uniforms.sunIntensity;
  output.ambientIntensity = uniforms.ambientIntensity;
  output.ambientColor = uniforms.ambientColor;

